// src/pages/HomePage.js

import React, { useEffect, useState } from "react";
import Slider from "react-slick";
import { getDailyBoxOffice, getMovieDetail } from "../api/boxofficeApi"; // API 경로 확인
import { getPosterFromTMDB } from "../api/tmdbApi"; // API 경로 확인
import MovieCard from "../components/MovieCard"; // MovieCard 경로 확인

import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchBoxOffice = async () => {
      // ... 이전과 동일한 데이터 fetching 로직 ...
      // ⭐️ MovieCard에 전달할 데이터 구조를 SCSS에 맞게 변경
      const enrichedMovies = await Promise.all(
        boxOfficeList.slice(0, 10).map(async (movie) => {
          const detail = await getMovieDetail(movie.movieCd);
          const year = detail.openDt?.substring(0, 4) || "";
          const posterUrl = await getPosterFromTMDB(movie.movieNm, year, { /* ... */ });

          return {
            id: movie.movieCd,
            title: movie.movieNm,
            englishTitle: detail.movieNmEn || "N/A",
            posterPath: posterUrl, // 'poster_path' 대신 'posterPath'로 이름 변경
            // 호버 시 필요한 상세 정보
            details: {
              "개봉일": detail.openDt ? detail.openDt.replace(/(\d{4})(\d{2})(\d{2})/, '$1.$2.$3') : "N/A",
              "감독": detail.directors?.[0]?.peopleNm || "N/A",
              "출연": detail.actors?.slice(0, 3).map(a => a.peopleNm).join(', ') + (detail.actors?.length > 3 ? '...' : ''),
            },
          };
        })
      );
      setMovies(enrichedMovies);
      // ...
    };
    fetchBoxOffice();
  }, []);

  const sliderSettings = {
    dots: false,
    infinite: true,
    speed: 500,
    slidesToShow: 5,
    slidesToScroll: 1,
    // ... 이전과 동일한 캐러셀 설정 ...
  };

  if (loading) return <div className="page-message">로딩 중...</div>;
  if (error) return <div className="page-message">에러: {error}</div>;

  return (
    <div className="homepage-container">
      <h1 className="page-title">박스오피스</h1>
      {/* ⭐️ SCSS의 .wrapper-card 클래스 적용 */}
      <div className="wrapper-card chart">
        <Slider {...sliderSettings}>
          {movies.map((movie) => (
            <MovieCard key={movie.id} movie={movie} size="m" />
          ))}
        </Slider>
      </div>
    </div>
  );
}

export default HomePage;
